    /// node enters the tree, so <c>Node._enter_tree</c> and <c>Node._ready</c>
    /// can read it.
    /// <code>
    /// func _init() -&gt; void:
    ///     Netw.configure_property(self, &amp;"pet_name").on_spawn()
    /// </code>
    /// </summary>
    public NetwPropertyConfig OnSpawn()
    {
        IntPtr answered = default;
        NetwThunks.Ptrcall0_IntPtr(_bindOnSpawn, Checked, ref answered);
        return NetwPropertyConfig.Adopt(answered);
    }
}
